-- AI Programming v2 enrichment — FULLY SELF-CONTAINED (no pgvector; embeddings are the separate 1b step).
-- Adds all needed columns, seeds variety caps, then populates all 650. Idempotent. Run this alone.

alter table public.exercises
  add column if not exists movement_pattern   text,
  add column if not exists movement_family    text,
  add column if not exists role               text,
  add column if not exists unilateral         boolean default false,
  add column if not exists is_compound        boolean default true,
  add column if not exists primary_muscles    text[],
  add column if not exists secondary_muscles  text[],
  add column if not exists contraindications  text[],
  add column if not exists plane              text;

create index if not exists exercises_pattern_idx on public.exercises (movement_pattern);
create index if not exists exercises_family_idx  on public.exercises (movement_family);

insert into public.feature_settings (key, value) values (
  'variety_caps',
  '{"maxPerFamilyPerWeek": {"glute_bridge": 1, "hip_thrust": 2, "face_pull": 2, "default": 3}, "maxSameIsolationPerSession": 1, "flagDuplicateExactAcrossWeek": true}'::jsonb
) on conflict (key) do nothing;

update public.exercises set movement_pattern='isolation_arm', movement_family='bicep_curl', role='accessory', unilateral=false, is_compound=false, primary_muscles='{biceps}', contraindications='{}' where id='dumbbell-curl';
